), inserted AS (
  INSERT INTO market_observations (company_id, import_batch_id, metric_key, period_kind, period_start, period_end, observation_date, target_period, comparison_period_start, comparison_period_end, value, unit, source_value, source_unit, source_name, source_locator, source_label, basis, statement_scope, capture_method, capture_method_original, status, verification_status, published_on, published_at, retrieved_on, retrieved_at, content_fingerprint)
  SELECT input.company_id, batch.import_batch_id, input.metric_key, input.period_kind, input.period_start, input.period_end, input.observation_date, input.target_period, input.comparison_period_start, input.comparison_period_end, input.value, input.unit, input.source_value, input.source_unit, input.source_name, input.source_locator, input.source_label, input.basis, input.statement_scope, input.capture_method, input.capture_method_original, input.status, input.verification_status, input.published_on, input.published_at, input.retrieved_on, input.retrieved_at, input.content_fingerprint
  FROM input CROSS JOIN batch
  ON CONFLICT (content_fingerprint) DO NOTHING
  RETURNING id
)
SELECT (SELECT import_batch_id FROM batch) AS import_batch_id,
       (SELECT count(*) FROM input) AS input_rows,
       (SELECT count(*) FROM inserted) AS inserted_rows,
       (SELECT count(*) FROM input) - (SELECT count(*) FROM inserted) AS skipped_duplicates;
COMMIT;
